import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (x1**2 - 5*np.cos(2*np.pi*x1) + x2**2 - 5*np.cos(2*np.pi*x2) + x3**2 - 5*np.cos(2*np.pi*x3)
            + 0.1 * x1 * (np.abs(x1) + np.abs(x2) + np.abs(x3))
            + 0.05 * (x1*x2 + x2*x3 + x1*x3)
            )

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return (5 + (x1 - 1)**2 - 5*np.cos(2*np.pi*(x1-1)) + (x2+1)**2 - 5*np.cos(2*np.pi*(x2+1)) + (x3-0.5)**2 - 5*np.cos(2*np.pi*(x3-0.5))
            + 0.1 * x1 * (np.abs(x1) + np.abs(x2) + np.abs(x3))
            + 0.05 * (x1*x2 + x2*x3 + x1*x3))
